#!/usr/bin/env Rscript
# ---------------------------------------------------------------------------
# Deploy the learnr tutorials to shinyapps.io as ONE app.
#
# shinyapps.io serves only one learnr tutorial per app, so this script first
# merges the three tutorials into a single one (Iris, Food and NMR as parts of
# one tutorial) and deploys that:
#   https://cpm-lumc.shinyapps.io/fos-tutorials/
#
# The merged tutorial is generated in ./shinyapps/ - edit the tutorials in
# inst/tutorials/, never the generated file.
#
# Usage:
#   Rscript deploy_shinyapps.R          # build and deploy
#   Rscript deploy_shinyapps.R build    # only build, e.g. to test locally with
#                                       # learnr::run_tutorial("shinyapps")
#
# Needs a registered shinyapps.io account, see the README (one-time setup with
# rsconnect::setAccountInfo()).
# ---------------------------------------------------------------------------

suppressWarnings(suppressMessages(library(rmarkdown)))

args       <- commandArgs(trailingOnly = TRUE)
build_only <- identical(args, "build")

account  <- "cpm-lumc"
server   <- "shinyapps.io"
app_name <- "fos-tutorials"

root         <- normalizePath(".")
tutorial_dir <- file.path(root, "inst", "tutorials")
app_dir      <- file.path(root, "shinyapps")

# The parts of the merged tutorial, in this order. The prefix is put in front
# of every chunk label (learnr needs unique labels) and the part name in front
# of every topic heading.
parts <- list(
  list(dir = "Iris-dataset",     prefix = "iris", name = "Iris"),
  list(dir = "Food-dataset",     prefix = "food", name = "Food"),
  list(dir = "NMR-metabolomics", prefix = "nmr",  name = "NMR")
)

# Files the tutorials read, copied next to the merged tutorial
data_files <- c("Food-dataset/foods.csv",
                "NMR-metabolomics/metabolomics.xlsx",
                "NMR-metabolomics/images")

# --- the global setup chunk ------------------------------------------------
# All three tutorials now share one R session, so the order in which the
# packages are attached decides which pca(), scores() and loadings() a bare
# call ends up with:
# - mixOmics and pls go first: NMR uses their perf() and plsr() unqualified.
# - pcaMethods goes after them, so the bare pca(), scores() and loadings() of
#   Iris and Food are the pcaMethods ones (NMR writes these out in full).
# - the tidyverse goes after that, restoring dplyr::select() over MASS::select()
#   (attached by mixOmics) and the base/stats functions pcaMethods masks.
SETUP_LIBS <- c("learnr", "mixOmics", "pls", "pcaMethods", "ggplot2", "dplyr",
                "tidyr", "plotly", "corrplot", "factoextra", "knitr", "DT",
                "readxl", "ComplexHeatmap", "circlize")

SETUP_HEAD <- c(
  "```{r setup, include=FALSE}",
  "# Generated by deploy_shinyapps.R from the tutorials in inst/tutorials/.",
  "# The package order matters, see deploy_shinyapps.R.",
  paste0("suppressPackageStartupMessages(library(", SETUP_LIBS, "))"),
  "",
  "tutorial_options(exercise.timelimit = 120)"
)

# --- helpers ---------------------------------------------------------------

is_fence <- function(line) grepl("^```", line)

# Split a tutorial into its YAML header, the body of its setup chunk (without
# the library() calls and tutorial_options(), which go in SETUP_HEAD) and the
# rest of the document.
split_tutorial <- function(lines, dir) {
  yaml_end <- which(lines == "---")[2]
  body     <- lines[-seq_len(yaml_end)]

  setup_start <- grep("^```\\{r setup[,}]", body)
  setup_end   <- setup_start + which(body[-seq_len(setup_start)] == "```")[1]
  setup       <- body[(setup_start + 1):(setup_end - 1)]

  # Everything up to tutorial_options() is the package block and its comments
  opts <- grep("^tutorial_options\\(", setup)
  if (length(opts) != 1) {
    stop(dir, ": expected exactly one tutorial_options() in the setup chunk",
         call. = FALSE)
  }
  libs <- sub(".*library\\(([^)]+)\\).*", "\\1",
              grep("library\\(", setup, value = TRUE))
  if (length(setdiff(libs, SETUP_LIBS))) {
    stop(dir, " loads package(s) missing from SETUP_LIBS: ",
         paste(setdiff(libs, SETUP_LIBS), collapse = ", "), call. = FALSE)
  }
  if (any(grepl("library\\(", setup[-seq_len(opts)]))) {
    stop(dir, ": library() calls must come before tutorial_options()",
         call. = FALSE)
  }

  list(setup = setup[-seq_len(opts)], body = body[-(setup_start:setup_end)])
}

# Prefix chunk labels, exercise.setup references and topic headings, and drop
# the "How to use this tutorial" topic (except for the first part).
rewrite_body <- function(body, part, keep_howto) {
  out      <- character(0)
  in_chunk <- FALSE
  skipping <- FALSE
  n_unlabelled <- 0

  for (line in body) {
    if (!in_chunk && grepl("^## ", line)) {
      howto    <- grepl("^## How to use this tutorial", line)
      skipping <- howto && !keep_howto
      if (!howto) line <- sub("^## ", paste0("## ", part$name, ": "), line)
    }
    if (is_fence(line)) {
      if (!in_chunk && grepl("^```\\{r[ ,}]", line)) {
        inner <- sub("^```\\{r\\s*", "", sub("\\}\\s*$", "", line))
        label <- trimws(strsplit(inner, ",")[[1]][1])
        if (is.na(label) || label == "" || grepl("=", label)) {
          n_unlabelled <- n_unlabelled + 1
          inner <- paste0("chunk-", n_unlabelled, ", ", inner)
        }
        inner <- paste0(part$prefix, "-", sub("^\\s*", "", inner))
        inner <- gsub("(exercise\\.setup\\s*=\\s*[\"'])",
                      paste0("\\1", part$prefix, "-"), inner)
        line  <- paste0("```{r ", sub(",\\s*$", "", inner), "}")
      }
      in_chunk <- !in_chunk
    }
    if (!skipping) out <- c(out, line)
  }
  out
}

# --- build -----------------------------------------------------------------

message("Building merged tutorial in ", app_dir)
dir.create(app_dir, showWarnings = FALSE)
# Start clean, but keep the rsconnect deployment record
old <- setdiff(list.files(app_dir, all.files = TRUE, no.. = TRUE), "rsconnect")
unlink(file.path(app_dir, old), recursive = TRUE)

for (f in data_files) {
  file.copy(file.path(tutorial_dir, f), app_dir, recursive = TRUE)
}

setups <- character(0)
bodies <- character(0)
for (i in seq_along(parts)) {
  part  <- parts[[i]]
  lines <- readLines(file.path(tutorial_dir, part$dir, "index.Rmd"), warn = FALSE)
  tut   <- split_tutorial(lines, part$dir)
  setups <- c(setups, "", paste0("# ==== ", part$name, " ", strrep("=", 60)),
              tut$setup)
  bodies <- c(bodies, rewrite_body(tut$body, part, keep_howto = i == 1))
}

yaml <- c(
  "---",
  'title: "Multivariate Data Analysis"',
  'subtitle: "PCA, PCA-Class and PLS-DA with R"',
  'description: "The three tutorials of the FOS course in one: PCA of the iris and food data sets, and PCA, PCA-Class and PLS-DA of an NMR metabolomics data set."',
  'author: "Rico Derks, Aswin Verhoeven"',
  "output:",
  "  learnr::tutorial:",
  "    progressive: true",
  "    allow_skip: true",
  "runtime: shiny_prerendered",
  "tutorial:",
  '  id: "fos-2026-all"',
  '  version: "1.0"',
  "---",
  ""
)

merged <- c(yaml, SETUP_HEAD, setups, "```", bodies)

labels <- sub("^```\\{r ([^, }]+).*", "\\1", grep("^```\\{r ", merged, value = TRUE))
dups   <- unique(labels[duplicated(labels)])
if (length(dups)) stop("Duplicate chunk labels: ", paste(dups, collapse = ", "),
                       call. = FALSE)
refs    <- regmatches(merged, regexpr("exercise\\.setup\\s*=\\s*[\"'][^\"']+", merged))
refs    <- sub(".*[\"']", "", refs)
missing <- setdiff(refs, labels)
if (length(missing)) stop("exercise.setup refers to unknown chunk(s): ",
                          paste(missing, collapse = ", "), call. = FALSE)

rmd <- file.path(app_dir, "index.Rmd")
writeLines(merged, rmd)

# Pre-render the tutorial, so the HTML is part of the bundle and the app does
# not have to knit the whole tutorial each time an instance starts. If the
# server considers the HTML out of date it simply renders it again.
render(rmd, envir = new.env(), quiet = TRUE)
message("Done: ", rmd)

if (build_only) quit(save = "no")

# --- deploy ----------------------------------------------------------------

suppressWarnings(suppressMessages(library(rsconnect)))

# pcaMethods, mixOmics and ComplexHeatmap come from Bioconductor. rsconnect
# can only tell shinyapps.io where to get them when the Bioconductor
# repositories are part of the repos option.
options(repos = BiocManager::repositories())

# Upload everything except the deployment record of rsconnect itself
files <- list.files(app_dir, recursive = TRUE, all.files = TRUE)
files <- files[!grepl("^rsconnect/", files)]

deployApp(
  appDir         = app_dir,
  appFiles       = files,
  appPrimaryDoc  = "index.Rmd",
  appName        = app_name,
  appTitle       = "Multivariate Data Analysis",
  account        = account,
  server         = server,
  forceUpdate    = TRUE,
  launch.browser = FALSE
)

message("\nDeployed: https://", account, ".shinyapps.io/", app_name, "/")
